package org.lbl.intranet.lineage.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import org.lbl.common.exception.BusinessException;
import org.lbl.intranet.dataasset.es.entity.EsFieldEntity;
import org.lbl.intranet.dataasset.es.entity.EsIndexEntity;
import org.lbl.intranet.dataasset.es.mapper.EsFieldMapper;
import org.lbl.intranet.dataasset.es.mapper.EsIndexMapper;
import org.lbl.intranet.dataasset.hbase.entity.HbaseFieldEntity;
import org.lbl.intranet.dataasset.hbase.entity.HbaseTableEntity;
import org.lbl.intranet.dataasset.hbase.mapper.HbaseFieldMapper;
import org.lbl.intranet.dataasset.hbase.mapper.HbaseTableMapper;
import org.lbl.intranet.lineage.entity.*;
import org.lbl.intranet.lineage.mapper.*;
import org.lbl.intranet.lineage.request.TransactionFieldSourceRequest;
import org.lbl.intranet.lineage.vo.*;
import org.lbl.intranet.transaction.entity.TransactionAssetEntity;
import org.lbl.intranet.transaction.field.entity.TransactionMessageFieldEntity;
import org.lbl.intranet.transaction.field.mapper.TransactionMessageFieldMapper;
import org.lbl.intranet.transaction.mapper.TransactionAssetMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
@Service public class LineageService {
 private final TransactionFieldSourceConfigMapper configs; private final FieldLineageRelationMapper relations; private final TransactionMessageFieldMapper fields; private final HbaseFieldMapper hbaseFields; private final HbaseTableMapper hbaseTables; private final EsFieldMapper esFields; private final EsIndexMapper esIndexes; private final TransactionAssetMapper transactions;
 public LineageService(TransactionFieldSourceConfigMapper configs, FieldLineageRelationMapper relations, TransactionMessageFieldMapper fields, HbaseFieldMapper hbaseFields, HbaseTableMapper hbaseTables, EsFieldMapper esFields, EsIndexMapper esIndexes, TransactionAssetMapper transactions) { this.configs=configs;this.relations=relations;this.fields=fields;this.hbaseFields=hbaseFields;this.hbaseTables=hbaseTables;this.esFields=esFields;this.esIndexes=esIndexes;this.transactions=transactions; }
 public List<LineageOptionVO> options() { List<LineageOptionVO> result=new ArrayList<>(); hbaseFields.selectList(null).forEach(f->{ HbaseTableEntity t=hbaseTables.selectById(f.getHbaseTableId()); if(t!=null) result.add(new LineageOptionVO("HBASE_FIELD",f.getId(),"HBase · "+t.getMarketName()+":"+t.getTableName()+"."+f.getColumnFamily()+":"+f.getFieldName()));}); esFields.selectList(null).forEach(f->{ EsIndexEntity i=esIndexes.selectById(f.getEsIndexId()); if(i!=null) result.add(new LineageOptionVO("ES_FIELD",f.getId(),"ES · "+i.getIndexName()+"."+f.getFieldName()));}); return result; }
 public TransactionFieldSourceVO get(Long fieldId) { requireField(fieldId); TransactionFieldSourceConfigEntity c=configs.selectById(fieldId); return view(fieldId,c); }
 @Transactional public TransactionFieldSourceVO save(Long fieldId, TransactionFieldSourceRequest r) { requireField(fieldId); String type=r.sourceType().trim(); if(!Set.of("PHYSICAL","CALLER_INPUT","CONSTANT","SYSTEM_GENERATED","COMPUTED").contains(type)) throw new BusinessException("取值方式无效"); List<TransactionFieldSourceRequest.Relation> items=r.relations()==null?List.of():r.relations(); if("PHYSICAL".equals(type)&&items.isEmpty()) throw new BusinessException("物理字段来源至少关联一个 HBase 或 ES 字段"); if(!"PHYSICAL".equals(type)&&!"COMPUTED".equals(type)&&!items.isEmpty()) throw new BusinessException("当前取值方式不能关联物理字段"); TransactionFieldSourceConfigEntity c=new TransactionFieldSourceConfigEntity(); c.setTargetFieldId(fieldId);c.setSourceType(type);c.setSourceDetail(blank(r.sourceDetail())); if(configs.selectById(fieldId)==null) configs.insert(c);else configs.updateById(c); relations.delete(new LambdaQueryWrapper<FieldLineageRelationEntity>().eq(FieldLineageRelationEntity::getTargetFieldId,fieldId)); for(var item:items){ if(!Set.of("HBASE_FIELD","ES_FIELD").contains(item.sourceType())||item.sourceFieldId()==null) throw new BusinessException("来源字段无效"); if(!Set.of("DIRECT","DERIVED","QUERY_CONDITION").contains(item.relationType())) throw new BusinessException("关系类型无效"); requireSource(item.sourceType(),item.sourceFieldId()); FieldLineageRelationEntity e=new FieldLineageRelationEntity();e.setTargetFieldId(fieldId);e.setSourceType(item.sourceType());e.setSourceFieldId(item.sourceFieldId());e.setRelationType(item.relationType());e.setExpression(blank(item.expression()));e.setRemark(blank(item.remark()));relations.insert(e); } return view(fieldId,c); }
 public List<ImpactItemVO> impact(String sourceType,Long sourceFieldId){ requireSource(sourceType,sourceFieldId); return relations.selectList(new LambdaQueryWrapper<FieldLineageRelationEntity>().eq(FieldLineageRelationEntity::getSourceType,sourceType).eq(FieldLineageRelationEntity::getSourceFieldId,sourceFieldId)).stream().map(r->{ TransactionMessageFieldEntity f=requireField(r.getTargetFieldId()); TransactionAssetEntity t=transactions.selectById(f.getTransactionId()); return new ImpactItemVO(t.getId(),t.getTransactionCode(),t.getTransactionName(),f.getId(),f.getMessageSide(),f.getFieldNameCn(),f.getFieldNameEn(),r.getRelationType(),r.getExpression(),r.getRemark());}).toList(); }
 public LineageGraphVO graph(String sourceType,Long sourceFieldId){
  requireSource(sourceType,sourceFieldId); List<LineageGraphVO.Node> nodes=new ArrayList<>(); List<LineageGraphVO.Edge> edges=new ArrayList<>(); String sourceId=sourceType+":"+sourceFieldId;
  if("HBASE_FIELD".equals(sourceType)){ HbaseFieldEntity field=hbaseFields.selectById(sourceFieldId); HbaseTableEntity table=hbaseTables.selectById(field.getHbaseTableId()); nodes.add(new LineageGraphVO.Node(sourceId,"HBASE_FIELD",field.getColumnFamily()+":"+field.getFieldName(),"HBase 字段")); nodes.add(new LineageGraphVO.Node("HBASE_TABLE:"+table.getId(),"HBASE_TABLE",table.getMarketName()+":"+table.getTableName(),"HBase 表")); edges.add(new LineageGraphVO.Edge(sourceId,"HBASE_TABLE:"+table.getId(),"属于")); }
  else { EsFieldEntity field=esFields.selectById(sourceFieldId); EsIndexEntity index=esIndexes.selectById(field.getEsIndexId()); nodes.add(new LineageGraphVO.Node(sourceId,"ES_FIELD",field.getFieldName(),"ES 字段")); nodes.add(new LineageGraphVO.Node("ES_INDEX:"+index.getId(),"ES_INDEX",index.getIndexName(),"ES 逻辑索引")); edges.add(new LineageGraphVO.Edge(sourceId,"ES_INDEX:"+index.getId(),"属于")); HbaseTableEntity table=hbaseTables.selectById(index.getHbaseTableId()); if(table!=null){ nodes.add(new LineageGraphVO.Node("HBASE_TABLE:"+table.getId(),"HBASE_TABLE",table.getMarketName()+":"+table.getTableName(),"HBase 回表目标")); edges.add(new LineageGraphVO.Edge("ES_INDEX:"+index.getId(),"HBASE_TABLE:"+table.getId(),"RowKey 回表")); } }
  for(ImpactItemVO item:impact(sourceType,sourceFieldId)){ String fieldId="TRANSACTION_FIELD:"+item.targetFieldId(); String transactionId="TRANSACTION:"+item.transactionId(); nodes.add(new LineageGraphVO.Node(fieldId,"TRANSACTION_FIELD",item.fieldNameCn()+" · "+item.fieldNameEn(),"交易"+("REQUEST".equals(item.messageSide())?"请求":"响应")+"字段")); nodes.add(new LineageGraphVO.Node(transactionId,"TRANSACTION",item.transactionCode(),item.transactionName())); edges.add(new LineageGraphVO.Edge(sourceId,fieldId,relationLabel(item.relationType()))); edges.add(new LineageGraphVO.Edge(fieldId,transactionId,"属于")); }
  return new LineageGraphVO(nodes.stream().collect(java.util.stream.Collectors.collectingAndThen(java.util.stream.Collectors.toMap(LineageGraphVO.Node::id,n->n,(a,b)->a,LinkedHashMap::new),m->new ArrayList<>(m.values()))),edges);
 }
 public List<LineageSearchOptionVO> search(String entryType,String keyword){ String value=keyword==null?"":keyword.trim().toLowerCase(Locale.ROOT); List<LineageSearchOptionVO> result=new ArrayList<>();
  if("TRANSACTION".equals(entryType)) transactions.selectList(null).stream().filter(t->contains(t.getTransactionCode(),value)||contains(t.getTransactionName(),value)).limit(200).forEach(t->result.add(new LineageSearchOptionVO("TRANSACTION",t.getId(),t.getTransactionCode()+" · "+t.getTransactionName(),"交易")));
  else if("TRANSACTION_FIELD".equals(entryType)) fields.selectList(null).stream().filter(f->contains(f.getFieldNameCn(),value)||contains(f.getFieldNameEn(),value)).limit(200).forEach(f->{TransactionAssetEntity t=transactions.selectById(f.getTransactionId()); if(t!=null) result.add(new LineageSearchOptionVO("TRANSACTION_FIELD",f.getId(),f.getFieldNameCn()+" · "+f.getFieldNameEn(),t.getTransactionCode()+" · "+("REQUEST".equals(f.getMessageSide())?"请求":"响应")+"字段"));});
  else if("HBASE_TABLE".equals(entryType)) hbaseTables.selectList(null).stream().filter(t->contains(t.getMarketName(),value)||contains(t.getTableName(),value)).limit(200).forEach(t->result.add(new LineageSearchOptionVO("HBASE_TABLE",t.getId(),t.getMarketName()+":"+t.getTableName(),"HBase 表")));
  else if("HBASE_FIELD".equals(entryType)) hbaseFields.selectList(null).stream().filter(f->contains(f.getFieldName(),value)||contains(f.getColumnFamily(),value)).limit(200).forEach(f->{HbaseTableEntity t=hbaseTables.selectById(f.getHbaseTableId());if(t!=null)result.add(new LineageSearchOptionVO("HBASE_FIELD",f.getId(),f.getColumnFamily()+":"+f.getFieldName(),t.getMarketName()+":"+t.getTableName()));});
  else throw new BusinessException("分析对象类型无效"); return result;
 }
 public LineageGraphVO graphByEntry(String entryType,Long entryId){ List<SourceRef> sources=new ArrayList<>();
  if("HBASE_FIELD".equals(entryType)){requireSource("HBASE_FIELD",entryId);sources.add(new SourceRef("HBASE_FIELD",entryId));}
  else if("HBASE_TABLE".equals(entryType)){requireTable(entryId);hbaseFields.selectList(new LambdaQueryWrapper<HbaseFieldEntity>().eq(HbaseFieldEntity::getHbaseTableId,entryId)).forEach(f->sources.add(new SourceRef("HBASE_FIELD",f.getId()))); esIndexes.selectList(new LambdaQueryWrapper<EsIndexEntity>().eq(EsIndexEntity::getHbaseTableId,entryId)).forEach(index->esFields.selectList(new LambdaQueryWrapper<EsFieldEntity>().eq(EsFieldEntity::getEsIndexId,index.getId())).forEach(f->sources.add(new SourceRef("ES_FIELD",f.getId()))));}
  else if("TRANSACTION_FIELD".equals(entryType)){requireField(entryId);relations.selectList(new LambdaQueryWrapper<FieldLineageRelationEntity>().eq(FieldLineageRelationEntity::getTargetFieldId,entryId)).forEach(r->sources.add(new SourceRef(r.getSourceType(),r.getSourceFieldId())));}
  else if("TRANSACTION".equals(entryType)){if(transactions.selectById(entryId)==null)throw new BusinessException("交易不存在");fields.selectList(new LambdaQueryWrapper<TransactionMessageFieldEntity>().eq(TransactionMessageFieldEntity::getTransactionId,entryId)).forEach(f->relations.selectList(new LambdaQueryWrapper<FieldLineageRelationEntity>().eq(FieldLineageRelationEntity::getTargetFieldId,f.getId())).forEach(r->sources.add(new SourceRef(r.getSourceType(),r.getSourceFieldId()))));}
  else throw new BusinessException("分析对象类型无效"); Map<String,LineageGraphVO.Node> nodes=new LinkedHashMap<>(); List<LineageGraphVO.Edge> edges=new ArrayList<>(); for(SourceRef source:sources){LineageGraphVO sub=graph(source.type(),source.id());for(LineageGraphVO.Node node:sub.nodes())nodes.putIfAbsent(node.id(),node);for(LineageGraphVO.Edge edge:sub.edges())if(edges.stream().noneMatch(item->item.source().equals(edge.source())&&item.target().equals(edge.target())&&item.label().equals(edge.label())))edges.add(edge);} return new LineageGraphVO(new ArrayList<>(nodes.values()),edges);
 }
 public void removeTarget(Long fieldId){ relations.delete(new LambdaQueryWrapper<FieldLineageRelationEntity>().eq(FieldLineageRelationEntity::getTargetFieldId,fieldId)); configs.deleteById(fieldId); }
 public void removeSource(String sourceType,Long sourceFieldId){ relations.delete(new LambdaQueryWrapper<FieldLineageRelationEntity>().eq(FieldLineageRelationEntity::getSourceType,sourceType).eq(FieldLineageRelationEntity::getSourceFieldId,sourceFieldId)); }
 private TransactionFieldSourceVO view(Long id,TransactionFieldSourceConfigEntity c){ return new TransactionFieldSourceVO(id,c==null?"UNCONFIGURED":c.getSourceType(),c==null?null:c.getSourceDetail(),relations.selectList(new LambdaQueryWrapper<FieldLineageRelationEntity>().eq(FieldLineageRelationEntity::getTargetFieldId,id)).stream().map(e->new TransactionFieldSourceVO.Relation(e.getId(),e.getSourceType(),e.getSourceFieldId(),sourceLabel(e.getSourceType(),e.getSourceFieldId()),e.getRelationType(),e.getExpression(),e.getRemark())).toList()); }
 private TransactionMessageFieldEntity requireField(Long id){ var f=fields.selectById(id);if(f==null)throw new BusinessException("交易字段不存在");return f;} private void requireSource(String type,Long id){if("HBASE_FIELD".equals(type)&&hbaseFields.selectById(id)!=null)return;if("ES_FIELD".equals(type)&&esFields.selectById(id)!=null)return;throw new BusinessException("来源字段不存在");} private String sourceLabel(String type,Long id){ for(var o:options())if(o.sourceType().equals(type)&&o.sourceFieldId().equals(id))return o.label();return "已删除字段";} private String blank(String v){return v==null||v.isBlank()?null:v.trim();}
 private String relationLabel(String type){ return switch(type){case "DIRECT"->"直接读取";case "DERIVED"->"加工得到";case "QUERY_CONDITION"->"查询条件";default->type;}; }
 private HbaseTableEntity requireTable(Long id){ HbaseTableEntity table=hbaseTables.selectById(id);if(table==null)throw new BusinessException("HBase 表不存在");return table;} private boolean contains(String value,String keyword){return value!=null&&value.toLowerCase(Locale.ROOT).contains(keyword);} private record SourceRef(String type,Long id) { }
}
